ecc_agent_script_include.script:
ms.include("IllumioMIDConstants");

var IllumioManageAsyncJobs = Class.create();

IllumioManageAsyncJobs.prototype = {
    initialize: function() {

        // set the parameters here
        // Read up here rather than at the four call sites that used to fetch it individually, so
        // the logger can be given its correlation context before anything logs.
        this.illumio_jobId = probe.getParameter('glide.jms.illumio_scheduled_job_id');
        this.logger = new IllumioLogUtil(this.illumio_jobId, 'IllumioManageAsyncJobs');
        // Only reached when glide.jms.chunk_size is missing or unparseable. The number itself
        // moved to DEFAULT_MID_BATCH_SIZE in IllumioMIDConstants, which carries the note on why
        // it is duplicated by hand from BATCH_SIZE_STANDARD; IllumioUpdateWorkloads now guards
        // `glide.jms.batch_size` the same way and reads the same constant, so the two cannot
        // drift. The property is kept because the warning below reads it.
        this._fallbackDefaultBatchSize = DEFAULT_MID_BATCH_SIZE;
        var url = String(ms.getConfigParameter("url"));
        if (url.charAt(url.length - 1) == '/') {
            url = url.substring(0, url.length - 1);
        }
        this.snowUrl = url;
        this.snowUsername = ms.getConfigParameter("mid.instance.username");
        this.snowPassword = ms.getConfigParameter("mid.instance.password");

        this.pceUrl = probe.getParameter('glide.jms.pce_url');
        this.pceEndpoint = probe.getParameter('glide.jms.pce_endpoint');
        this.pceAuthorization = probe.getParameter('glide.jms.pce_authorization');
        this.currentJobSysID = probe.getParameter('glide.jms.pce_async_job_sys_id') + '';
        this.pceMIDProxy = probe.getParameter('glide.jms.enable_pce_mid_proxy');
        this.batchSize = probe.getParameter('glide.jms.chunk_size');
        this.batchSize = parseInt(this.batchSize, 10) || this._fallbackDefaultBatchSize;
        if (this.batchSize < 1) {
            this.logger._warning(
                "Invalid 'x_illu2_illumio.batch_size_standard' provided. Proceeding with " +
                this._fallbackDefaultBatchSize +
                " as default value. Please set a valid value to " +
                "'x_illu2_illumio.batch_size_standard' property."
            );
            this.batchSize = this._fallbackDefaultBatchSize;
        }

        this.timeZone = probe.getParameter('glide.jms.time_zone');
        this.SimpleDF = Packages.java.text.SimpleDateFormat;
        this.TimeZone = Packages.java.util.TimeZone;

        // R48. The async job result is streamed to disk and then walked one element at a time,
        // so neither the response body nor the parsed graph is ever held whole.
        this.File = Packages.java.io.File;
        // Jackson, from the MID Server's own agent/lib -- jackson-core and jackson-databind are
        // both there. Confirmed on the MID host 2026-10-06; this is not a bundled dependency of
        // this app and nothing here ships it.
        //
        // IT SPLITS THE ARRAY, IT DOES NOT CONVERT THE RECORDS. Each element is handed back as
        // JSON text and parsed by the engine's own JSON.parse, so the conversion below operates
        // on exactly the kind of object it always did. Walking Jackson's JsonNode API instead
        // would mean rewriting every `typeof x == 'object'` and `x[key].length` in this file
        // against different semantics, which is a correctness risk taken for nothing.
        this.JsonFactory = Packages.com.fasterxml.jackson.core.JsonFactory;
        this.ObjectMapper = Packages.com.fasterxml.jackson.databind.ObjectMapper;
        this.TEMP_FILE_PREFIX = 'illumio-asyncresult-';

        this.snowDateFormat = this.SimpleDF("yyyy-MM-dd HH:mm:ss");
        this.illumioDateFormat = this.SimpleDF("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");

        this.snowDateFormat.setTimeZone(this.TimeZone.getTimeZone('GMT'));
        this.illumioDateFormat.setTimeZone(this.TimeZone.getTimeZone('UTC'));

        // L2: moved ABOVE the IllumioPCEUtils construction, which now takes retryParams. It used
        // to be parsed four lines below it, so passing it at construction without this move would
        // have handed over an undefined.
        this.retryParams = DEFAULT_RETRY_PARAMS;
        try {
            this.retryParams = JSON.parse(probe.getParameter('glide.jms.retry_params'));
        } catch (e) {
            this.logger._except('IllumioManageAsyncJobs - Cannot parse the JSON of retry parameters');
        }

        this.utils = new IllumioPCEUtils(this.timeZone, this.illumio_jobId, this.retryParams);

        this.protocol = this.utils.getPortFromUrl(this.pceUrl);

        var decodedAuth = this.utils.decodeBase64(this.pceAuthorization);
        decodedAuth = decodedAuth.split(":");
        this.pceUsername = decodedAuth[0];
        this.pcePassword = decodedAuth.slice(1).join(':');

        this.pceHttpClient = new IllumioHTTPClient(this.pceUrl, this.pceUsername, this.pcePassword, this.protocol, this.pceMIDProxy, this.retryParams, this.illumio_jobId);
        this.snHttpClient = new IllumioHTTPClient(this.snowUrl, this.snowUsername, this.snowPassword, "443", null, this.retryParams, this.illumio_jobId);
        // illumio_jobId used to be read here, at the very bottom of initialize -- after both HTTP
        // clients and after the logger. It is read at the top now so the correlation context
        // exists before anything can log.
    },

    /**
     * Probe entry point.
     *
     * W5/W6: the body is _run(). This wrapper exists for two things the body cannot do for
     * itself.
     *
     * W6 -- one boundary line the moment the probe starts, pushed to the instance rather than
     * left in agent0.log. A transport failure (MID offline, the message never picked up, a probe
     * name that does not resolve) runs none of our code, so nothing inside here can report it.
     * The instance logging "queued for the MID" with no probe-entered line after it is what
     * says the break is in the transport and not in either half.
     *
     * W5 -- the push budget for this run is reset here, before the milestone below, or that line
     * would be charged against whatever the previous run in this MID JVM spent. There is nothing
     * to do at the end: each line is pushed to the instance as it happens, so a run that throws
     * has already delivered the errors that led up to the throw.
     */
    run: function() {
        this.logger.resetPushBudget();
        this.logger._milestone('Probe entered.');
        return this._run();
    },

    _run: function() {

        if (
            this.utils.checkCancelledJobStatus(this.illumio_jobId)
        ) {
            return;
        }

        this.requiredOperation = probe.getParameter('glide.jms.operation');
        this.configSysId = probe.getParameter('glide.jms.illumio_pce_configuration_id');

        // perform required async job operation
        if (this.requiredOperation == 'create_async_job') {
            this.logger._info('IllumioManageAsyncJobs --------- Creating new async job on PCE');
            this.createNewAsyncJobRequest();

        } else if (this.requiredOperation == 'get_async_job_status') {
            this.logger._info('IllumioManageAsyncJobs - Getting async job status from PCE');
            this.getAsyncJobStatus(this.configSysId);

        } else {
            this.logger._error('IllumioManageAsyncJobs - No async operation provided.');
        }
    },

    /**
     * Start async job on PCE
     * @return {Boolean} whether async job was created successfully or not.
     */
    createNewAsyncJobRequest: function() {

        try {
            // Required header to indicate async job
            var headers = {
                Prefer: 'respond-async'
            };

            if (this.utils.checkCancelledJobStatus(this.illumio_jobId)) {
                return;
            }

            // getting all workloads
            var response = this.pceHttpClient.get(this.pceEndpoint, '', headers);

            if (response.hasError) {
                this.logger._error("Failed to create async job on PCE.");
                this.handleException("Failed to create async job on PCE, Please check MID server logs for more details");
                return false;
            }

            var responseHeaders = response.headers;
            for (var key in responseHeaders) {
                responseHeaders[key.toLowerCase()] = responseHeaders[key];
            }
            // Async job data to be stored in Async Jobs table
            var payload = {
                job_location: responseHeaders.location,
                job_status: 'new',
                retry_interval: responseHeaders['retry-after'],
                mapping_table_name: probe.getParameter('glide.jms.mapping_table_name'),
                result_table_name: probe.getParameter('glide.jms.result_table_name'),
                keys_to_map: probe.getParameter('glide.jms.keys_to_map'),
                primary_key_to_map: probe.getParameter('glide.jms.primary_key_to_map'),
                illumio_job_id: probe.getParameter('glide.jms.illumio_scheduled_job_id'),
                job_identifier: probe.getParameter('glide.jms.job_identifier')
            };

            if (this.utils.checkCancelledJobStatus(this.illumio_jobId)) {
                return;
            }

            /*var post = */
            var endpoint = TABLE_API + ASYNC_JOB_TABLE;
            response = this.snHttpClient.post(endpoint, '', null, payload);

            if (response.hasError) {
                this.logger._error("Failed to create async job on SNOW, Response Code: " + response.status);
                this.handleException("Failed to create async job on SNOW, Please check MID server logs for more details.");
                return false;
            }
        } catch (exception) {
            this.logger._except('IllumioManageAsyncJobs - Exception occurred while creating async job on PCE. Exception: ' + exception);
            this.handleException('Exception occurred while creating async job on PCE. Exception: ' + exception);
        }

    },

    /**
     * Get status of async job running on PCE
     * @return {Boolean} whether status was successful or not.
     */
    getAsyncJobStatus: function(configSysId) {

        try {
            var jobStatus = ASYNC_JOB_STATUS_FAILED;
            var resultUrl = '';
            var isResultsAvailable = false;


            if (this.utils.checkCancelledJobStatus(this.illumio_jobId)) {
                return;
            }

            var response = this.pceHttpClient.get(this.pceEndpoint, '');

            if (response.hasError) {
                this.logger._error('Exception occurred while getting async job status from PCE, Response Code: ' + response.status);
                this.handleException('Exception occurred while getting async job status from PCE, Please check MID server logs for more details.');
                return false;
            }
            jobStatus = response.data.status.toLowerCase();
            this.logger._debug('IllumioManageAsyncJobs - Job status: ' + jobStatus);

            // If job status is done, get result's href
            if (jobStatus == 'done') {

                resultUrl = response.data.result.href;

                if (!resultUrl) {
                    this.logger._error('IllumioManageAsyncJobs - Job completed but datafiles url is not present in response. Setting job status to failed.');
                    jobStatus = ASYNC_JOB_STATUS_FAILED;
                } else {
                    isResultsAvailable = this.getAsyncJobResults(resultUrl, configSysId);
                }
            }

            // Results are available and stored in mapping tables
            // Set status to 'ready_to_map' to indicate getting CMDB servers and map with PCE data
            if (isResultsAvailable) {
                jobStatus = ASYNC_JOB_STATUS_READY_TO_MAP;
            }

            var payload = {
                job_status: jobStatus,
                job_result_location: resultUrl,
                retry_count: parseInt(probe.getParameter('glide.jms.retry_count')) + 1
            };

            var endpoint = TABLE_API + ASYNC_JOB_TABLE + "/" + this.currentJobSysID;
            response = this.snHttpClient.put(endpoint, '', null, payload);

            if (response.hasError) {
                this.logger._error('Exception occurred while updating async job status in SNOW, Response Code: ' + response.status);
                this.handleException('Exception occurred while updating async job status on SNOW, Please check MID server logs for more details.');
                return false;
            }

        } catch (exception) {
            this.logger._except('IllumioManageAsyncJobs - Exception occurred while getting async job status from PCE. Exception: ' + exception);
            this.handleException('Exception occurred while getting async job status from PCE. Exception: ' + exception);
        }
    },

    /**
     * Walk the top-level array in a JSON file, one element at a time.
     *
     * Jackson's streaming parser reads the file incrementally: `readValueAsTree` consumes exactly
     * one array element and advances, so the live set is one record regardless of how many the
     * PCE returned. The element is re-serialised and handed to the engine's own JSON.parse -- see
     * the note in initialize on why the conversion is NOT done against JsonNode.
     *
     * WHY A LIBRARY AND NOT A HAND-ROLLED SPLITTER. Finding array element boundaries in a byte
     * stream means getting escaped quotes, backslash-escaped backslashes, structural characters
     * inside string values, UTF-8 sequences straddling a read boundary and split surrogate pairs
     * all correct, and getting any of them wrong corrupts a record rather than failing. Jackson
     * has seen every one of those. The only thing written here is the loop.
     *
     * TRUNCATION IS AN ERROR, NOT A SHORT READ. If the download was cut off, `nextToken` returns
     * null before END_ARRAY and this throws. That matters more than it looks: a truncated result
     * that returned 31,000 of 50,000 workloads would be indistinguishable from a successful run,
     * and discovery would mark the missing ones unknown and sync would then create duplicates on
     * the PCE. An exception is recoverable; a silently short result is not.
     *
     * @param {java.io.File} file File holding a JSON array
     * @param {Function} onElement Called with each parsed element; return false to stop
     * @returns {Number} Elements walked
     */
    _eachResultElement: function(file, onElement) {
        var factory = new this.JsonFactory();
        // The codec is what makes readValueAsTree available; jackson-core alone cannot build a
        // tree. Both jars are on the MID.
        factory.setCodec(new this.ObjectMapper());

        var parser = factory.createParser(file);
        var walked = 0;

        try {
            // Enum identity is compared through its name rather than with ==. Rhino can wrap the
            // same Java enum constant in a new host object per access, which makes reference
            // equality an unreliable thing to branch on; the name is stable.
            var first = parser.nextToken();
            if (!first || String(first) !== 'START_ARRAY') {
                throw 'Expected a JSON array at the top level of the async job result, found ' +
                    (first ? String(first) : 'an empty body');
            }

            while (true) {
                var token = parser.nextToken();

                if (!token) {
                    throw 'Async job result ended after ' + walked + ' element(s) without closing ' +
                        'its array. The download was truncated -- treating this as a failure ' +
                        'rather than a short result.';
                }
                if (String(token) === 'END_ARRAY') {
                    break;
                }

                // One element, as text, then parsed by the engine. Scoped to this iteration so
                // both forms are collectable as soon as onElement returns.
                var elementText = String(parser.readValueAsTree().toString());
                walked++;

                if (onElement(JSON.parse(elementText)) === false) {
                    break;
                }
            }
        } finally {
            try { parser.close(); } catch (ignored) {}
        }

        return walked;
    },

    /**
     * Get results of async jobs from result location
     * @param {String} resultsLocation location of the result.
     * @return {Boolean} whether request was successful or not.
     */
    getAsyncJobResults: function(resultsLocation, configSysId) {

        // Declared out here so the finally can delete it whichever way the body leaves.
        var resultFile = null;

        try {


            if (this.utils.checkCancelledJobStatus(this.illumio_jobId)) {
                return;
            }

            // Required keys. Read BEFORE the download now -- a missing probe parameter fails the
            // job either way, and there is no reason to spend a 100 MB transfer discovering it.
            var resultTable = probe.getParameter('glide.jms.result_table_name');
            var job_identifier = probe.getParameter('glide.jms.job_identifier');
            var keysToMap = JSON.parse(probe.getParameter('glide.jms.keys_to_map'));
            var scheduled_job_id = probe.getParameter('glide.jms.illumio_scheduled_job_id');
            var primaryKey = probe.getParameter('glide.jms.primary_key');

            if (!resultTable || !keysToMap || !primaryKey) {
                this.logger._error('IllumioManageAsyncJobs - Missing result table or columns of result table or primary key. Setting job status to failed.');
                this.handleException('Missing result table or columns of result table or primary key. Setting job status to failed');
                return false;
            }

            // MOVED UP from just above the 'Fetched:' line, where it used to be built. The lines
            // between here and there -- "Available. Started fetching.", the download size, any
            // failure -- all want it, and without it they read as the other async job's.
            var tag = (job_identifier + "").charAt(0).toUpperCase() + (job_identifier + "").slice(1);

            // The PCE has finished preparing the result and handed back a location; this is the
            // moment the transfer actually starts. Polling can sit on "Checking fetch status" for
            // minutes, so the line that says waiting is over is worth its own entry.
            //
            // _milestone, NOT _info. _info is ms.log only -- it reaches agent0.log on the MID host
            // and never the instance, so as _info this line was invisible to the only person who
            // needed it. This is W6's case exactly: a handoff boundary whose ABSENCE localizes the
            // break. "Checking fetch status" then nothing means the PCE never said done; this line
            // then nothing means the download itself is where it died. One push per async job, so
            // it is bounded by job count and cannot flood the wire.
            this.logger._milestone('[' + tag + '] Available. Started fetching.');

            var fetchStartTime = new Date().getTime();

            // R48. Straight to disk. The old `pceHttpClient.get` built the whole body as a byte[],
            // copied it to a UTF-16 String and then parsed the lot into one object graph -- three
            // full-size forms inside one try block, which is what threw OutOfMemoryError against
            // 50,000 workloads on 2026-10-06.
            resultFile = this.File.createTempFile(
                this.TEMP_FILE_PREFIX + this.illumio_jobId + '-', '.json');

            var response = this.pceHttpClient.getToFile('/api/v2' + resultsLocation, '', resultFile);

            if (response.hasError) {
                this.logger._error('No results received from PCE for current async job, Response status: ' + response.status);
                this.handleException('No results received from PCE for current async job, Please check MID server logs for more details.');
                return false;
            }

            // Syslog, not the job record. _updateJobRecord costs a GET plus a PUT against the
            // Table API and the existing two lines below already carry the run totals; this one
            // is here so "it downloaded but died converting" stays distinguishable from "it never
            // downloaded", which the job record alone cannot tell you.
            //
            // _milestone for the same reason as the line above: that distinction is drawn by
            // someone reading syslog_app_scope, and _info never gets there. The comment above
            // said "Syslog" while the call said agent0.log -- it was wrong, not just quiet.
            // Tagged now too; untagged it read as whichever async job the reader assumed.
            this.logger._milestone('[' + tag + '] Downloaded ' + resultFile.length() +
                ' byte(s) to ' + resultFile.getAbsolutePath());

            var resultData = [];
            // Records PCE returned that carry no primary key. They are dropped on purpose --
            // see the log line below -- but the drop is invisible without a count.
            var missingPrimaryKey = 0;

            // R48, and R27's rule -- "nothing may duplicate a structure the size of the result" --
            // finally applied to the MID side, which that audit never reached.
            //
            // THREE THINGS THAT USED TO STAND BETWEEN HERE AND A RECORD ARE GONE:
            //
            //   1. `pceHttpClient.get(...)`, which built the body as a byte[], copied it to a
            //      UTF-16 String and parsed the lot into one graph. Replaced by getToFile above.
            //   2. `if (!Array.isArray(response.data))`, the shape guard. _eachResultElement
            //      enforces the same thing harder -- it throws unless the first token is
            //      START_ARRAY -- so the check moved rather than disappeared.
            //   3. `response.data = JSON.parse(JSON.stringify(response.data));`
            //
            // The third was a deep clone of the entire result and the single largest allocation
            // in the run: the old graph, a complete JSON string built from it, and a new graph,
            // all live across one statement. It bought nothing -- the array was already freshly
            // parsed and privately owned, and nothing below mutates it. It was also the only line
            // in this method carrying no explanation, which is what flagged it. Kept here as a
            // record because it was removed deliberately, not lost in the rewrite.
            //
            // response.data = JSON.parse(JSON.stringify(response.data));

            var self = this;
            // `tag` is built above, before the download, so the lines either side of it can use
            // it. Not redeclared here -- ES5 var hoisting would make a second declaration a
            // silent no-op that reads as if it were doing something.
            var stagingElapsedMs = 0;
            var batchCount = 0;
            var stagingFailed = false;
            var cancelled = false;

            // THE WALK AND THE STAGING ARE NOW ONE PASS. Previously the whole result was converted
            // into `resultData` and only then drained in batches, so the converted form of every
            // record was live at once. Here a batch is POSTed as soon as it fills and the array is
            // emptied, which makes `batchSize` -- not the PCE's workload count -- the ceiling on
            // everything this method holds.
            var resultLength = this._eachResultElement(resultFile, function(resultObj) {

                if (resultObj[primaryKey]) {
                    var requredDataObj = {};
                    // WAS keysToMap.map(...), used as a forEach -- a throwaway array per record,
                    // so one per element across the whole walk.
                    for (var k = 0; k < keysToMap.length; k++) {
                        var key = keysToMap[k];
                        if (key == 'agent') {
                            var agent = resultObj[key];
                            if (agent['href'])
                                requredDataObj[key] = true;
                            else
                                requredDataObj[key] = false;
                        } else if (key == "interfaces") {
                            var interfaceRequiredFields = [];
                            var interfaceLength = resultObj[key].length;
                            for (var indexForInterface = 0; indexForInterface < interfaceLength; indexForInterface++) {
                                var IPObject = {};
                                IPObject["name"] = resultObj[key][indexForInterface].name;
                                IPObject["address"] = resultObj[key][indexForInterface].address;
                                interfaceRequiredFields.push(IPObject);
                            }
                            requredDataObj[key] = JSON.stringify(interfaceRequiredFields);

                        } else {
                            requredDataObj[key] = typeof resultObj[key] == 'object' ? JSON.stringify(resultObj[key]) : resultObj[key] + "";
                        }
                    }
                    resultData.push(requredDataObj);
                } else {
                    missingPrimaryKey++;
                }

                if (resultData.length < self.batchSize) {
                    return true;
                }

                // Checked at a batch boundary, which is the same cadence the old code used --
                // once before staging began. It is now checked repeatedly, so a cancel during a
                // long walk is noticed rather than waited out.
                if (self.utils.checkCancelledJobStatus(self.illumio_jobId)) {
                    cancelled = true;
                    return false;
                }

                var stagedAt = new Date().getTime();
                var ok = self._stageBatch(resultTable, configSysId, resultData, job_identifier, batchCount);
                stagingElapsedMs += (new Date().getTime() - stagedAt);

                if (!ok) {
                    stagingFailed = true;
                    return false;
                }
                batchCount++;
                return true;
            });

            if (cancelled) {
                return;
            }
            if (stagingFailed) {
                this.handleException(
                    'Exception occurred while posting results to SNOW, Please check MID server logs for more details.'
                );
                return false;
            }

            // The remainder, which is every run whose count is not an exact multiple of batchSize.
            if (resultData.length > 0) {
                var lastStagedAt = new Date().getTime();
                if (!this._stageBatch(resultTable, configSysId, resultData, job_identifier, batchCount)) {
                    this.handleException(
                        'Exception occurred while posting results to SNOW, Please check MID server logs for more details.'
                    );
                    return false;
                }
                stagingElapsedMs += (new Date().getTime() - lastStagedAt);
                batchCount++;
            }

            var convertedLength = resultLength - missingPrimaryKey;
            var fetchElapsed = ((new Date().getTime() - fetchStartTime - stagingElapsedMs) / 1000).toFixed(2);
            this.logger._debug('IllumioManageAsyncJobs - Total records : ' + convertedLength + ", broken down into batches of " + this.batchSize);

            // The primary key is the only field discovery can match on -- 'hostname' for
            // workloads, 'value' for labels -- so a record without one cannot be mapped and is
            // dropped by design. Reported on the fetch line rather than its own, because
            // _updateJobRecord costs a GET plus a PUT against the SNOW Table API, and because
            // the count is only meaningful next to the number that was kept.
            //
            // Worth knowing when this is non-zero for workloads: PCE workloads created through
            // the PCE UI have Name set but Hostname null, so they never reach the mapping table
            // and the CMDB CI that should have matched one classifies as unknown instead.
            //
            // BOTH LINES KEEP THEIR EXACT WORDING AND ORDER. They are the two run totals the job
            // record carries for this phase and anything reading the job record -- a human or the
            // regression pass -- matches on their shape. Only the timings underneath changed:
            // fetch now excludes the staging it is interleaved with, so the two still add up to
            // the phase rather than double-counting it.
            var fetchLog = '[' + tag + '] Fetched: ' + convertedLength + ' (' + fetchElapsed + 's)';
            if (missingPrimaryKey > 0) {
                fetchLog += '; skipped ' + missingPrimaryKey + ' with no ' + primaryKey;
            }

            this._updateJobRecord(scheduled_job_id, {
                logs: fetchLog
            });

            var stagingElapsed = (stagingElapsedMs / 1000).toFixed(2);
            this._updateJobRecord(scheduled_job_id, {
                logs: '[' + tag + '] Staged: ' + batchCount + ' batch(s) (Size: ' + this.batchSize + ') (' + stagingElapsed + 's)'
            });

            this.logger._info('IllumioManageAsyncJobs - Posted all records to SNOW');
            return true;

        } catch (exception) {
            this.logger._except('IllumioManageAsyncJobs - Exception occurred while getting async job results. Exception: ' + exception);
            this.handleException('Exception occurred while getting async job results. Exception: ' + exception);
            return false;
        } finally {
            // Deleted on every path, including the cancel and the truncation throw. A MID Server
            // temp directory is not somewhere a 100 MB async result should accumulate, and unlike
            // the preview file this one has no sweep behind it -- nothing else knows the name.
            if (resultFile) {
                try {
                    if (!resultFile['delete']()) {
                        this.logger._warning('IllumioManageAsyncJobs - Could not delete temp file ' +
                            resultFile.getAbsolutePath() + '. It will have to be removed by hand.');
                    }
                } catch (cleanupException) {
                    this.logger._warning('IllumioManageAsyncJobs - Temp file cleanup failed: ' + cleanupException);
                }
            }
        }
    },

    /**
     * POST one converted batch to its staging table and empty the array.
     *
     * Split out of the old staging loop because the walk now calls it mid-stream rather than
     * after everything is converted. `resultData` is emptied here, not by the caller, so that a
     * batch is never both POSTed and still held.
     *
     * @param {String} resultTable Staging table name
     * @param {String} configSysId PCE Configuration sys_id
     * @param {Array} resultData Converted records; emptied on success
     * @param {String} jobIdentifier 'workloads' or 'labels', for the log line
     * @param {Number} batchIndex Zero-based batch number, for the log line
     * @returns {Boolean} whether the POST succeeded
     */
    _stageBatch: function(resultTable, configSysId, resultData, jobIdentifier, batchIndex) {
        var payload = {
            illumio_pce_configuration: configSysId,
            json_data: JSON.stringify(resultData)
        };

        this.logger._debug('Proceeding to write the payload of ' + jobIdentifier + ' batch ' +
            batchIndex + ' (' + resultData.length + ' record(s))');

        var resp = this.snHttpClient.post(TABLE_API + resultTable, '', null, payload);
        if (resp.hasError) {
            this.logger._error('Cannot insert the data in staging table');
            return false;
        }

        // Emptied in place rather than reassigned -- the caller holds this same array across
        // every batch, so a new one here would leave it filling the old.
        resultData.length = 0;
        return true;
    },

    /**
     * Handles exception by logging and setting job status as failed
     * @param {String} exception thrown by methods.
     */
    handleException: function(exception) {

		if (this.currentJobSysID && this.currentJobSysID !== 'null') {
			var payload = {
				job_status: ASYNC_JOB_STATUS_FAILED
			};
			this.snHttpClient.put(
				TABLE_API + ASYNC_JOB_TABLE + "/" + this.currentJobSysID, 
				'', 
				null, 
				payload
			);
		}

        var illumio_job_id = probe.getParameter('glide.jms.illumio_scheduled_job_id');
        if (illumio_job_id) {
            var payload = {
                job_status: JOB_STATUS_FAILED,
                logs: exception,
                job_completed: this.snowDateFormat.format(new Date()) + ""
            };
            this._updateJobRecord(illumio_job_id, payload);
        }
    },

    /**
     * Updates scheduled job record with given parameters.
     *
     * One GET, one PUT, and the PUT carries only the fields that changed. Same rewrite as
     * IllumioUpdateWorkloads._updateJobRecord and for the same reasons -- see the note there:
     * `job_status` is actually fetched now (all the status comparisons here were against
     * undefined), the whole-record PUT and its `illumio_pce_configuration` re-flatten are gone,
     * and `String.replaceAll` was ES2021 on a Rhino engine.
     *
     * @param {String} jobSysId sys_id of the job record
     * @param {Object} jobContent Fields to write. `logs` is appended to what is already there;
     *                 everything else is replaced.
     */
    _updateJobRecord: function(jobSysId, jobContent) {

        var snowGetUrl =
            TABLE_API +
            SCHEDULED_JOB_TABLE +
            '?sysparm_fields=logs,job_status&sysparm_query=sys_id=' + jobSysId +
            '&sysparm_limit=1';

        var putUrl =
            TABLE_API + SCHEDULED_JOB_TABLE + '/' + jobSysId;

        var response = this.snHttpClient.get(snowGetUrl, '');
        if (response.hasError || !response.data || !response.data.result ||
            response.data.result.length === 0) {
            this.logger._error(
                '[_updateJobRecord] Error while checking status of given job on ServiceNow. ' +
                'Proceeding with further actions.'
            );
            return false;
        }

        var jobRecord = response.data.result[0];
        var status = String(jobRecord.job_status);

        if (CANCELLED_JOB_STATUSES.indexOf(status) > -1) {
            return true;
        }

        if (status == JOB_STATUS_FAILED) {
            this.logger._info(
                '[_updateJobRecord] Given job has already failed. Aborting further actions.'
            );
            return false;
        }

        var payload = {};
        for (var key in jobContent) {
            if (jobContent.hasOwnProperty(key) && key != 'logs') {
                payload[key] = jobContent[key];
            }
        }

        if (jobContent.hasOwnProperty('logs')) {
            var existingLogs = String(jobRecord.logs == null ? '' : jobRecord.logs)
                .replace(/\\n/g, '\n');
            // W1: no per-line timestamp. The same line is emitted to syslog_app_scope, which
            // timestamps it there, and the job log is a milestone list rather than a trace.
            payload.logs = existingLogs + (existingLogs ? '\n' : '') + jobContent.logs;
            // W2: the job log and Application Logs carry the same milestones. Anything worth a
            // line on the job record is worth one in the correlated trail, where it sits next to
            // the MID-side detail that produced it. _milestone pushes it to the instance too, so
            // a job-log line and its surrounding context are readable from one place.
            this.logger._milestone(String(jobContent.logs));
        }

        var putResponse = this.snHttpClient.put(putUrl, '', null, payload);
        if (putResponse.hasError) {
            return false;
        }

        this.logger._debug('The Scheduled Job had updated the values with the logs');
    },

    type: "IllumioUpdateKnownWorkloads"
};
